<?php
declare(strict_types=1);
$visibleDatasets=$selectedMetric==='all'?array_slice($statisticsDatasets,0,4,true):[$selectedMetric=>$statisticsDatasets[$selectedMetric]];
?>
<div data-inventory-statistics-panel><div class="inventory-kpis"><?php foreach(array_slice((array)($inventoryStatistics['kpis']??[]),0,6) as $kpi): ?><article class="inventory-kpi"><span><?= e((string)($kpi['label']??'-')); ?></span><strong><?= e($inventoryFormat($kpi['value']??0,(string)($kpi['kind']??'quantity'))); ?></strong></article><?php endforeach; ?></div><div class="inventory-chart-grid" style="margin-top:14px"><?php foreach($visibleDatasets as $dataset): ?><?php $rows=(array)($dataset['rows']??[]);$max=1.0;foreach($rows as $row){$max=max($max,(float)($row['value']??0));}$kind=(string)($dataset['kind']??'quantity'); ?><article class="inventory-chart" data-inventory-stat-chart><div class="portal-card-head"><strong><?= e((string)($dataset['title']??'-')); ?></strong><span class="portal-pill"><?= e((string)($inventoryStatistics['start_date']??'')); ?> - <?= e((string)($inventoryStatistics['end_date']??'')); ?></span></div><?php foreach($rows as $row): ?><div class="inventory-chart-row"><span><?= e((string)($row['label']??'-')); ?></span><i class="inventory-chart-track"><b style="width:<?= e((string)max(3,min(100,round(((float)($row['value']??0)/$max)*100,2)))); ?>%"></b></i><strong><?= e($inventoryFormat($row['value']??0,$kind)); ?></strong></div><?php endforeach; ?><?php if($rows===[]): ?><p class="inventory-empty">Secilmis dovrde melumat yoxdur.</p><?php endif; ?></article><?php endforeach; ?></div></div>
